// ===== 設定 =====
const TZ = 'Asia/Tokyo';
const DAYS_BEFORE = 7;          // 何日前に通知するか
const HEARTBEAT_DOW = 1;        // 死活通知の曜日 0=日 1=月 ... 6=土 / null で無効

// シートの1行目と完全に一致させること
const COL = {
  date:    '登録日',
  service: 'サービス名',
  price:   '金額',
  card:    'カード',
  cycle:   '周期',
  status:  '状態',
};
// 上記6列のうち1つでも見つからなければアラートを送る
const ACTIVE = '利用中';               // これ以外の状態は通知対象外
// ================

const pad  = (n) => String(n).padStart(2, '0');
const yen  = (n) => '\u00A5' + n.toLocaleString('ja-JP');
const fmt  = (d) => `${d.getUTCFullYear()}/${pad(d.getUTCMonth() + 1)}/${pad(d.getUTCDate())}`;
const norm = (s) => String(s).replace(/[\s\u3000]/g, '');  // ヘッダーの余分な空白のみ吸収

// 異常時はエラーを投げずに「アラートLINE」を返す（無言で止まらないため）
const alert = (body) => [{
  json: { kind: 'alert', text: `\u26A0\uFE0F サブスク通知が正しく動いていません\n\n${body}` }
}];

// ---------- JSTの今日 ----------
const todayStr = new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit'
}).format(new Date());
const [ty, tm, td] = todayStr.split('-').map(Number);
const today = new Date(Date.UTC(ty, tm - 1, td));

// ---------- 前回実行日（取りこぼし補完用） ----------
// 本番のスケジュール実行でのみ保存される。手動実行では持ち越されない。
const sd = $getWorkflowStaticData('global');
let gap = 1;  // 前回の正常実行から何日経ったか（通常は1）
if (sd.lastRunDate) {
  const [ly, lm, ld] = String(sd.lastRunDate).split('-').map(Number);
  const last = new Date(Date.UTC(ly, lm - 1, ld));
  if (!isNaN(last)) gap = Math.round((today - last) / 86400000);
}
if (!(gap >= 1)) gap = 1;              // 同日再実行・時計異常は通常判定
gap = Math.min(gap, DAYS_BEFORE + 1);  // 長期停止後は「本日〜7日後」の範囲のみ（過ぎた更新はさかのぼらない）

// ---------- 入力チェック ----------
const rows = $input.all().filter(i => i.json && Object.keys(i.json).length > 0);
if (rows.length === 0) {
  return alert('スプレッドシートから1行もデータを取得できませんでした。\n共有設定・シート名・読み取り範囲を確認してください。');
}

// ---------- ヘッダー確認 ----------
// 1行目だけでなく全行のキーの和集合で判定する
// （Sheets APIは行末の空セルを省略するため、先頭行のitemに列が欠けることがある）
const headerKeys = [...new Set(rows.flatMap(i => Object.keys(i.json)))]
  .filter(k => k !== 'row_number');
const normMap = new Map(headerKeys.map(k => [norm(k), k]));

const KEY = {};
for (const [field, name] of Object.entries(COL)) {
  if (normMap.has(norm(name))) KEY[field] = normMap.get(norm(name));
}

const missing = Object.keys(COL).filter(f => !KEY[f]);
if (missing.length > 0) {
  const want = missing.map(f => `\u300C${COL[f]}\u300D`).join('、');
  const unknown = headerKeys.filter(k => !Object.values(KEY).includes(k));
  return alert(
    `列名が一致しません。\n\n` +
    `見つからない列（${missing.length}件）:\n${want}\n\n` +
    `シートで検出したヘッダー:\n${headerKeys.join(' / ') || '(なし)'}` +
    (unknown.length ? `\n\n該当なしのヘッダー:\n${unknown.join(' / ')}` : '') +
    `\n\n1行目の列名が変更・削除されていないか確認してください。`
  );
}

const get = (row, field) => (KEY[field] ? row[KEY[field]] : undefined);

// ---------- 次回更新日を求める ----------
function nextRenewal(signup, isYearly, from) {
  const day = signup.getUTCDate();
  if (isYearly) {
    for (let y = from.getUTCFullYear(); y <= from.getUTCFullYear() + 1; y++) {
      const mo   = signup.getUTCMonth();
      const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
      const cand = new Date(Date.UTC(y, mo, Math.min(day, last)));
      if (cand >= from && cand > signup) return cand;
    }
    return null;
  }
  for (let i = 0; i < 14; i++) {
    const y    = from.getUTCFullYear();
    const mo   = from.getUTCMonth() + i;
    const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
    const cand = new Date(Date.UTC(y, mo, Math.min(day, last)));
    if (cand >= from && cand > signup) return cand;
  }
  return null;
}

// ---------- 集計 ----------
const hits = [];        // 今日通知すべきもの（未実行日の取りこぼし分を含む）
const upcoming = [];    // 死活通知用の直近予定
const badDate = [];     // 登録日が読めない行
const noStatus = [];    // 状態が空欄の行
let activeCount = 0;

for (const item of rows) {
  const row = item.json;

  const raw  = get(row, 'date');
  const name = get(row, 'service') || '(名称未設定)';

  // 完全な空行はスキップ
  const hasAnyValue = [raw, get(row, 'service'), get(row, 'price')]
    .some(v => String(v ?? '').trim() !== '');
  if (!hasAnyValue) continue;

  const status = String(get(row, 'status') ?? '').trim();
  if (status !== ACTIVE) {
    if (status === '') noStatus.push(name);
    continue;
  }

  const m = String(raw ?? '').match(/(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})/);
  if (!m) { badDate.push(name); continue; }
  const signup = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  if (isNaN(signup)) { badDate.push(name); continue; }

  activeCount++;

  const isYearly = String(get(row, 'cycle') ?? '月').includes('年');
  const renewal  = nextRenewal(signup, isYearly, today);
  if (!renewal) continue;

  const entry = {
    service: name,
    price: Number(String(get(row, 'price') ?? '').replace(/[^0-9.\-]/g, '')) || 0,
    card: String(get(row, 'card') ?? '').trim(),
    cycle: isYearly ? '年' : '月',
    renewal,
    daysLeft: Math.round((renewal - today) / 86400000),
  };

  upcoming.push(entry);
  // 通常（gap=1）は daysLeft === DAYS_BEFORE と同じ。
  // 未実行日があった場合は、その日に通知するはずだった分まで窓を広げて拾う。
  if (entry.daysLeft <= DAYS_BEFORE && entry.daysLeft > DAYS_BEFORE - gap) hits.push(entry);
}

// ここまで到達した＝判定が完了した実行のみ「実行済み」として記録する
// （途中のalertで返った日は記録されず、翌日以降の窓に取りこぼしとして含まれる）
sd.lastRunDate = todayStr;

// 登録日が壊れている行は、通常はハートビート/更新通知の脚注で知らせる。
// ハートビートを無効にしている場合のみ、従来どおり毎日アラートを送る。
if (HEARTBEAT_DOW === null && badDate.length > 0 && hits.length === 0) {
  return alert(
    `登録日を日付として読み取れない行があります:\n` +
    `${badDate.slice(0, 5).join('、')}${badDate.length > 5 ? ` 他${badDate.length - 5}件` : ''}\n\n` +
    `\u300C2026/07/29\u300D の形式で入力してください。`
  );
}

const footnote = () => {
  const notes = [];
  if (noStatus.length > 0) {
    notes.push(`状態が未入力: ${noStatus.slice(0, 3).join('、')}${noStatus.length > 3 ? ` 他${noStatus.length - 3}件` : ''}`);
  }
  if (badDate.length > 0) {
    notes.push(`登録日が不正（\u300C2026/07/29\u300D の形式で入力）: ${badDate.slice(0, 3).join('、')}${badDate.length > 3 ? ` 他${badDate.length - 3}件` : ''}`);
  }
  return notes.length ? `\n\n\u26A0\uFE0F ${notes.join('\n\u26A0\uFE0F ')}` : '';
};

// ---------- 更新予定あり ----------
if (hits.length > 0) {
  hits.sort((a, b) =>
    a.renewal - b.renewal ||
    (a.cycle === b.cycle ? b.price - a.price : a.cycle === '年' ? -1 : 1)
  );

  const single = new Set(hits.map(h => +h.renewal)).size === 1;
  const when = (h) => (h.daysLeft === 0 ? '本日' : `${h.daysLeft}日後`);

  const lines = hits.map(h => {
    const meta = [h.cycle === '年' ? '年払い' : '月払い', h.card].filter(Boolean).join(' / ');
    const date = single ? '' : `${fmt(h.renewal)}・${when(h)} / `;
    return `\u30FB${h.service}  ${yen(h.price)}\n\u3000\uFF08${date}${meta}\uFF09`;
  });
  const total = hits.reduce((s, h) => s + h.price, 0);

  const headline = single
    ? `${fmt(hits[0].renewal)}\uFF08${when(hits[0])}\uFF09に以下が更新されます。`
    : `未通知だった分を含め、以下の更新が近づいています。`;

  const text =
    `\uD83D\uDD14 サブスク更新のお知らせ\n` +
    `${headline}\n\n` +
    `${lines.join('\n')}\n\n` +
    `${single ? 'この日の請求合計' : '請求合計'}: ${yen(total)}` +
    footnote();

  return [{ json: { kind: 'renewal', text, count: hits.length, total } }];
}

// ---------- 死活通知（週1回）----------
if (HEARTBEAT_DOW !== null && today.getUTCDay() === HEARTBEAT_DOW) {
  upcoming.sort((a, b) => a.renewal - b.renewal);
  const next = upcoming.slice(0, 3)
    .map(u => `\u30FB${fmt(u.renewal)}  ${u.service}  ${yen(u.price)}`)
    .join('\n');

  const text =
    `\u2705 サブスク監視は動作中です\n` +
    `${todayStr.replace(/-/g, '/')} 時点 / 利用中 ${activeCount}件\n\n` +
    `直近の更新予定:\n${next || '(予定なし)'}` +
    footnote();

  return [{ json: { kind: 'heartbeat', text, count: activeCount } }];
}

// 通常の「何もない日」は送信しない
return [];

